#!/usr/bin/env python3
"""Produce documentation only; never change a frozen model, recipe or metric."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
r=json.loads((root/'study/results.json').read_text())
pct=lambda x:f'{100*x:.1f}'
lines=['# Measured results', '', 'One locked confirmation run, 29 October 2026. The model and recipe bytes did not change after confirmation. [Raw metrics](../study/results.json), [frozen selection decisions](../study/deployment-selection.json), [all attempted recipes](../study/recipe-registry.json), and [integrity audit](../study/confirmation-integrity.json) are retained.', '', '**No acceptable composed candidate passed the frozen selection contract.** Vision repairs reduced measured deficits but did not retain every required capability. Text met its confirmation floors, but its prior selection gate failed, so it remains unaccepted. These are experimental artifacts, not production-ready all-capability models.', '', '## Vision confirmation', '', 'Accuracy in percent. Main floors: clean 88; left/right/inverted 80. Each row evaluates 360 original source images in each of four domains. Every transformed view stays within its source partition. Writer IDs are unavailable. Seed29 reuses seed11 merge scalars; its earlier pilot exposure prevents a wholly unseen-seed claim.', '', '| Seed | Method | Clean | Left | Right | Inverted | Floors met | Worst deficit, points |', '|---|---|---:|---:|---:|---:|---:|---:|']
for seed in r['vision']:
 for row in seed['rows']:
  if row['name'] in ['base','expert-left','expert-right','expert-inverted','task_arithmetic','ties','dare','tsv','regmean','repair-strongest','joint_finetune_strongest','ensemble-reference']:
   m=row['confirmation'];q=row['summary'];lines.append(f"| {seed['seed']} | {row['name']} | "+' | '.join(pct(m[t]['accuracy']) for t in ['clean','left','right','inverted'])+f" | {round(q['fraction_floors_met']*4)}/4 | {pct(q['worst_deficit'])} |")
lines+=['', 'TSV and RegMean actually executed. Weight-only operators were tuned with selection labels, so the whole selection pipeline is not data-free. TSV uses compressed/polar-decorrelated task subspaces; RegMean uses calibration activation statistics, bias augmentation and declared regularization. These are disclosed small-MLP implementations, not claims of exact full-paper replication. The probability ensemble retains three complete experts and is a quality/cost reference.', '', 'RegMean→repair improves clean accuracy by 2.2 and 4.2 points on seeds11/29. Clean regression against the corresponding base is 8.9 and 2.5 points, within the registered 10-point limit on confirmation, while absolute and other task floors still fail. On seed11 the joint comparator meets more floors (2/4) than repair (0/4), while repair has a slightly smaller worst deficit. Neither dominates the other.', '', '## Text adapter confirmation', '', 'Balanced exact-text-deduplicated SMS subset, 262 source messages across four domains. Original labels are [ham, spam]. This is fixed character-feature classification, not a generative language-model benchmark. Near-duplicate templates can span splits.', '', '| Method | Clean | Uppercase | Leet | Underscores | Floors met | Worst deficit, points |', '|---|---:|---:|---:|---:|---:|---:|']
for row in r['text']['rows']:
 m=row['confirmation'];q=row['summary'];lines.append(f"| {row['name']} | "+' | '.join(pct(m[t]['accuracy']) for t in ['clean','uppercase','leet','underscores'])+f" | {round(q['fraction_floors_met']*4)}/4 | {pct(q['worst_deficit'])} |")
lines+=['', 'Text floors were clean75% and each transformed domain72%, with at most3 points clean regression relative to the ordinary merge. Repair leet selection accuracy was71.43%, below72%. Its later78.24% confirmation result cannot retroactively accept it. Clean confirmation accuracy stays86.26% after repair, a7.25-point regression from the text base. Three rank4 specialist adapters were trained with frozen base weights, and their folded dense experts match adapter logits exactly on three changed inputs each ([audit](../study/text-adapter-audit.json)).', '', '## Controls and ablations', '', 'All following vision seed11 controls were registered before confirmation. Main floors apply except the explicitly custom easy control.', '', '| Recipe | Gradient example accesses | Accepted rank upper bound | Floors met | Worst deficit, points |', '|---|---:|---:|---:|---:|']
seed=r['vision'][0]
for row in seed['rows']:
 if row['name'] in ['repair','ablation-no_priority','ablation-fixed_rank','ablation-no_protection','ablation-no_correction','insufficient-calibration','easy-merge','conflict-ordinary','conflict-repaired']:
  lines.append(f"| {row['name']} | {row.get('gradient_examples','see report')} | {row.get('rank_used',0)} | {round(row['summary']['fraction_floors_met']*4)}/4 | {pct(row['summary']['worst_deficit'])} |")
lines+=['', 'Removing priority performs better here but uses2864 gradient accesses versus537, so it does not isolate priority at equal data cost. Fixed rank1 matches default arithmetic-repair metrics with a smaller accepted rank; removing protection is identical in this run. These ablations do not establish individual benefits of priority, variable-rank allocation or protection. Core tests separately verify that the protection gate rejects damaging proposals.', '', 'The easy merge repeats one expert three times and uses custom selection-derived floors (selection accuracy minus3 points), including very weak inverted/right requirements. It verifies the zero-correction fast path; it is not success on the main contract. Conflict repair and one-example-per-task calibration both fail the main contract. Pilot inversion specialists were weak; their failures and the pre-confirmation training amendment remain in the ledger.', '', '## Cost and calibration', '', 'Strongest repair and same-start joint fine-tuning each use4 gradient steps and716 calibration example accesses, with zero distillation-teacher calls. Joint draws from the same permitted four-domain pool. Both select with the same held-out selection partition. Repair tests72 interventions and evaluates79,920 selection examples plus2864 calibration-metric examples, totaling83,500 model-example accesses including gradients. Each joint LR trial evaluates1080 selection examples and the three-LR search is logged separately. **This is a matched gradient-data/step budget, not a matched total-compute, selection-cost or exact-FLOP comparison.** RegMean also incurs3 parent activation forwards/537 calibration examples before repair. No general efficiency/superiority claim follows.', '', 'Text repair uses520 gradient accesses,58,016 selection evaluations and2080 calibration-metric examples (60,616 total), rank upper bound6,72 interventions, zero parent or distillation calls.', '', '| Selected experimental artifact | Total stored bytes | Weights bytes, full head included | Warm forward median ms | p95 ms |', '|---|---:|---:|---:|---:|']
calibration_lines=[]
for label,row in [('vision seed11',next(x for x in r['vision'][0]['rows'] if x['name']=='repair-strongest')),('text',next(x for x in r['text']['rows'] if x['name']=='repair'))]:
 l=row['latency'];lines.append(f"| {label} | {row['stored_artifact_bytes']:,} | {row['weights_bytes']:,} | {l['median_ms']:.6f} | {l['p95_ms']:.6f} |")
 calibration_lines+=['',f"{label} ten-bin expected calibration errors: "+', '.join(f"{n}={m['ece_10']:.4f}" for n,m in row['confirmation'].items())+'.']
lines+=calibration_lines
lines+=['',f"All143 retained artifacts occupy{r['total_artifact_bytes']:,} bytes, including all heads and the retained text adapter factors/metadata. A fresh finalization process peaked at252,641,280 bytes RSS and repeated arithmetic merge+repair in14.02s with identical weights; its process scope also includes ledger/joint-control setup and excludes expert training. Confirmation process peak RSS was{r['peak_rss_bytes']:,} bytes. Per-seed expert training/build timing and per-candidate wall times remain in raw results/registry. Strongest repair took20.84s and11.63s on seeds11/29; selected same-start joint trials took0.46s and3.15s. These noisy local wall times are not normalized throughput benchmarks.", '', 'Latency is cached model-forward time only, Apple M4 CPU, four Torch threads, batch1,20 warmups and100 repeats. It excludes preprocessing, disk loading, CLI startup and workbench requests. Large p95 outliers are retained. No speedup ratio is claimed. Core artifact loading verifies hashes and includes manifest overhead in stored bytes.', '', '## Evidence limits', '', 'No external pretrained weights were used. The public datasets are old and may be present in external pretraining corpora; this local-from-scratch study makes no claims about future imported foundation models. Digit domains are artificial transformations from one source, SMS templates may overlap, there are only two vision initializations and one text initialization, and no confidence interval or significance claim is made. Source indices are disjoint and exact duplicates grouped; this does not establish writer/template-disjoint generalization.', '', 'The low-rank method is labeled data-assisted optimization. Gradient similarity only proposes directions; controlled selection interventions establish local measured effects, not a general causal account of interference. Empirical floors are not universal behavior guarantees. Removing an expert from a recipe is rebuilding, not machine unlearning. Failed bounded search means no acceptable candidate found, not impossibility.', '', 'Both selected static artifacts changed outputs in fresh installed processes while the OS denied all parent-project reads, caches and network ([vision](../study/independent-vision.json), [text](../study/independent-text.json)). The initial clean-install failures are retained; the missing runtime packaging dependency was fixed explicitly. Software malformed/nonfinite/adversarial-input checks do not certify adversarial ML robustness.']
(root/'docs/RESULTS.md').write_text('\n'.join(lines)+'\n')
